def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1

    grid = []
    for i in range(n):
        row = []
        for j in range(m):
            row.append(int(input_data[idx])); idx += 1
        grid.append(row)

    q = int(input_data[idx]); idx += 1

    INF = float('inf')

    # Precompute W_c[i][j] = vertical distance within column c from row i to row j
    W = []
    for c in range(m):
        wc = [[INF] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                total = 0
                for k in range(min(i, j), max(i, j) + 1):
                    total += grid[k][c]
                wc[i][j] = total
        W.append(wc)

    # Matrix multiplication in (min, +) semiring
    def mat_mult(A, B):
        C = [[INF] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == INF:
                    continue
                for j in range(n):
                    if B[k][j] == INF:
                        continue
                    val = A[i][k] + B[k][j]
                    if val < C[i][j]:
                        C[i][j] = val
        return C

    # Build segment tree
    tree_size = 4 * m
    tree = [None] * tree_size

    def build(node, start, end):
        if start == end:
            tree[node] = [row[:] for row in W[start]]
        else:
            mid = (start + end) // 2
            build(2 * node, start, mid)
            build(2 * node + 1, mid + 1, end)
            tree[node] = mat_mult(tree[2 * node], tree[2 * node + 1])

    build(1, 0, m - 1)

    def query(node, start, end, l, r):
        if r < start or end < l:
            return None
        if l <= start and end <= r:
            return tree[node]
        mid = (start + end) // 2
        left_mat = query(2 * node, start, mid, l, r)
        right_mat = query(2 * node + 1, mid + 1, end, l, r)
        if left_mat is None:
            return right_mat
        if right_mat is None:
            return left_mat
        return mat_mult(left_mat, right_mat)

    # Precompute H_c: min cost (i,c) to (j,c) using cols <= c
    H = [None] * m
    H[0] = [row[:] for row in W[0]]

    for c in range(1, m):
        hc = [[INF] * n for _ in range(n)]
        # Option 1: stay in column c
        for i in range(n):
            for j in range(n):
                hc[i][j] = W[c][i][j]
        # Option 2: go to c-1 and come back
        # H_c[i][j] = min over x,y of (W_c[i][x] + a[x][c-1] + H_{c-1}[x][y] + W_c[y][j])
        for i in range(n):
            for j in range(n):
                for x in range(n):
                    for y in range(n):
                        val = W[c][i][x] + grid[x][c-1] + H[c-1][x][y] + W[c][y][j]
                        if val < hc[i][j]:
                            hc[i][j] = val
        H[c] = hc

    # Precompute R_c: min cost (i,c) to (j,c) using cols >= c
    R = [None] * m
    R[m-1] = [row[:] for row in W[m-1]]

    for c in range(m - 2, -1, -1):
        rc = [[INF] * n for _ in range(n)]
        # Option 1: stay in column c
        for i in range(n):
            for j in range(n):
                rc[i][j] = W[c][i][j]
        # Option 2: go to c+1 and come back
        for i in range(n):
            for j in range(n):
                for x in range(n):
                    for y in range(n):
                        val = W[c][i][x] + grid[x][c+1] + R[c+1][x][y] + W[c][y][j]
                        if val < rc[i][j]:
