long long dp(long long remaining, int idx) {
    if (remaining == 0) return 1;
    if (remaining < 0 || idx < 0) return 0;

    if (memo.count({remaining, idx})) {
        return memo[{remaining, idx}];
    }

    long long result = dp(remaining, idx - 1);
    result += dp(remaining - fib[idx], idx - 1);

    memo[{remaining, idx}] = result;
    return result;
}

